package com.jbrempresa.backend.dto.compras;
import java.math.BigDecimal;import java.time.*;import com.jbrempresa.backend.entity.Compra;import jakarta.validation.constraints.*;
public final class CompraDtos{private CompraDtos(){}
 public record Entrada(Long perIdCom,Long perIdVen,Long proId,@PositiveOrZero BigDecimal comImpSub,@PositiveOrZero BigDecimal comImpDes,@PositiveOrZero BigDecimal comImpIva,@PositiveOrZero BigDecimal comImpTot,@PositiveOrZero BigDecimal comImpPag,@PositiveOrZero BigDecimal comImpPen,LocalDate comFecPre,LocalDate comFecPed,LocalDate comFecAlb,LocalDate comFecFac,LocalDate comFecPag){public Compra entidad(){Compra v=new Compra();v.setPerIdCom(perIdCom);v.setPerIdVen(perIdVen);v.setProId(proId);v.setComImpSub(comImpSub);v.setComImpDes(comImpDes);v.setComImpIva(comImpIva);v.setComImpTot(comImpTot);v.setComImpPag(comImpPag);v.setComImpPen(comImpPen);v.setComFecPre(comFecPre);v.setComFecPed(comFecPed);v.setComFecAlb(comFecAlb);v.setComFecFac(comFecFac);v.setComFecPag(comFecPag);return v;}}
 public record Salida(Long comId,Long empId,Long perIdCom,Long perIdVen,Long proId,BigDecimal comImpSub,BigDecimal comImpDes,BigDecimal comImpIva,BigDecimal comImpTot,BigDecimal comImpPag,BigDecimal comImpPen,LocalDate comFecPre,LocalDate comFecPed,LocalDate comFecAlb,LocalDate comFecFac,LocalDate comFecPag,Boolean comAct,String comUsuMov,LocalDateTime comFecMov){public static Salida desde(Compra v){return new Salida(v.getComId(),v.getEmpId(),v.getPerIdCom(),v.getPerIdVen(),v.getProId(),v.getComImpSub(),v.getComImpDes(),v.getComImpIva(),v.getComImpTot(),v.getComImpPag(),v.getComImpPen(),v.getComFecPre(),v.getComFecPed(),v.getComFecAlb(),v.getComFecFac(),v.getComFecPag(),v.getComAct(),v.getComUsuMov(),v.getComFecMov());}}
}
